-- Get employees's companyId
UPDATE t
SET CompanyId = c.CompanyId
FROM #tmpEmp t
INNER JOIN dbo.CompanyEmployee c WITH(NOLOCK) ON c.EmpId = t.UserId

INSERT INTO dbo.LookupData (LookupId, Name, Value, CompanyId)
SELECT DISTINCT 
	1,
	t.JobTitle, 
	CASE t.JobCategory
		WHEN 'Staff' THEN 2
		WHEN 'Executive' THEN 3
		WHEN 'Management' THEN 5
		ELSE NULL
	  END,
	t.CompanyId
FROM #tmpEmp t 
WHERE NOT EXISTS (
	SELECT 1 
	FROM dbo.LookupData l
	WHERE l.LookupId = 1 AND l.Name = t.JobTitle AND l.CompanyId = t.CompanyId
);

UPDATE e
SET e.FullName = ISNULL(t.FullName, e.NickName)
	,e.DOB = t.DateOfBirth
	,e.Gender = CASE 
			WHEN t.Gender = 'Male' THEN 1 
			ELSE 0 
		END
	,e.JobLevelId = jl.JobLevelId
	,e.JobTitleId = ld.Id
	,e.ManagementLevelId = ml.ManagementLevelId
FROM dbo.Employee e WITH(ROWLOCK)
INNER JOIN #tmpEmp t ON t.UserId = e.EmpId
LEFT JOIN dbo.JobLevel jl WITH(NOLOCK) ON jl.Name = t.JobLevel
LEFT JOIN dbo.LookupData AS ld WITH (NOLOCK) ON ld.Name = t.JobTitle AND ld.CompanyId = t.CompanyId AND ld.LookupId = 1
LEFT JOIN ManagementLevel ml WITH (NOLOCK) ON t.ManagementGrade = ml.Name

UPDATE e
SET e.CountryCode = CASE t.Nationality
            WHEN 'TWN' THEN 'TW'
            WHEN 'MYS' THEN 'MY'
            WHEN 'SGP' THEN 'SG'
            WHEN 'BNN' THEN 'BN'
            ELSE NULL
        END
	,e.IsLocal = CASE 
			WHEN t.Category = 'Local' THEN 1 
			ELSE 0 
		END
	,e.CompanyDate = t.CompanyDate
FROM dbo.EmployeeSummary e WITH(ROWLOCK)
INNER JOIN #tmpEmp t ON t.UserId = e.EmpId

